wc -l samples/floatingIslandDiorama.ts; mkdir -p scratch/floatingIslandDiorama; cat > scratch/floatingIslandDiorama/probe.ts <<'EOF'
import * as THREE from "three";
import build from "../../samples/floatingIslandDiorama";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
console.log("size", box.getSize(new THREE.Vector3()), "min", box.min, "max", box.max);
let meshes = 0, tris = 0; const cols = new Set<string>();
root.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { meshes++; const g = m.geometry; tris += (g.index ? g.index.count : g.attributes.position.count) / 3; const mat = m.material as THREE.MeshStandardMaterial; cols.add(mat.color.getHexString() + (mat.map ? "m" : "")); } });
console.log({ meshes, tris, colours: cols.size });
EOF
timeout 300 npx tsx scratch/floatingIslandDiorama/probe.ts 2>&1 | tail -30
